1	:host {
2	    display: block;
3	    --rail-card-width: 172px;
4	    --rail-gap: 14px;
5	    --rail-radius: 12px;
6	}
7	
8	.rail {
9	    display: flex;
10	    flex-direction: column;
11	    gap: 12px;
12	}
13	
14	.rail__header {
15	    display: flex;
16	    align-items: center;
17	    justify-content: space-between;
18	    gap: 12px;
19	    padding: 0 2px;
20	    // Tighter height cap — keeps rail chapter markers compact
21	    min-height: 24px;
22	}
23	
24	.rail__title {
25	    margin: 0;
26	    display: inline-flex;
27	    align-items: baseline;
28	    gap: 8px;
29	    font-size: 1.125rem; // 18px — matches Netflix rail-title scale
30	    font-weight: 600;
31	    line-height: 1.2;
32	    letter-spacing: -0.012em;
33	    color: var(--app-heading-color, #1a1d23);
34	}
35	
36	// Muted count badge, tabular numerals for alignment, sits just after label.
37	.rail__count {
38	    font-size: 0.78rem;
39	    font-weight: 500;
40	    line-height: 1;
41	    color: var(--app-muted-color, #8891a4);
42	    font-variant-numeric: tabular-nums;
43	    // Tiny capsule to read as a "count chip", not a number-in-text
44	    padding: 2px 8px;
45	    border-radius: 999px;
46	    background: color-mix(
47	        in srgb,
48	        var(--app-muted-color, #8891a4) 18%,
49	        transparent
50	    );
51	    letter-spacing: 0;
52	}
53	
54	.rail__see-all {
55	    display: inline-flex;
56	    align-items: center;
57	    gap: 2px;
58	    padding: 4px 8px 4px 10px;
59	    border-radius: 999px;
60	    font-size: 0.78rem;
61	    font-weight: 500;
62	    line-height: 1;
63	    letter-spacing: 0.005em;
64	    color: var(--app-muted-color, #8891a4);
65	    text-decoration: none;
66	    transition:
67	        color 0.15s ease,
68	        background-color 0.15s ease;
69	
70	    mat-icon {
71	        font-size: 16px;
72	        width: 16px;
73	        height: 16px;
74	        transition: transform 0.15s ease;
75	    }
76	
77	    &:hover {
78	        color: var(--app-selection-color, #2f7bff);
79	        background: color-mix(
80	            in srgb,
81	            var(--app-selection-color, #2f7bff) 12%,
82	            transparent
83	        );
84	
85	        mat-icon {
86	            transform: translateX(2px);
87	        }
88	    }
89	
90	    &:focus-visible {
91	        outline: 2px solid var(--app-selection-color, #2f7bff);
92	        outline-offset: 2px;
93	    }
94	}
95	
96	.rail__viewport {
97	    position: relative;
98	    min-width: 0;
99	
100	    // Soft edge gradients hint at horizontal scroll without any interaction.
101	    // Anchored to the viewport so they appear/disappear in sync with the
102	    // chevrons' `.rail__chev--visible` state.
103	    &::before,
104	    &::after {
105	        content: '';
106	        position: absolute;
107	        top: 0;
108	        bottom: 0;
109	        width: 32px;
110	        pointer-events: none;
111	        z-index: 1;
112	        opacity: 0;
113	        transition: opacity 0.2s ease;
114	    }
115	
116	    &::before {
117	        left: 0;
118	        background: linear-gradient(
119	            to right,
120	            var(--app-content-bg, #161a22) 0%,
121	            transparent 100%
122	        );
123	    }
124	
125	    &::after {
126	        right: 0;
127	        background: linear-gradient(
128	            to left,
129	            var(--app-content-bg, #161a22) 0%,
130	            transparent 100%
131	        );
132	    }
133	
134	    // Show the correct edge gradient when scroll is possible in that direction
135	    &:has(.rail__chev--left.rail__chev--visible)::before {
136	        opacity: 0.9;
137	    }
138	
139	    &:has(.rail__chev--right.rail__chev--visible)::after {
140	        opacity: 0.9;
141	    }
142	
143	    &:hover .rail__chev--visible {
144	        opacity: 1;
145	        transform: translateY(-50%) scale(1);
146	    }
147	}
148	
149	.rail__track {
150	    display: flex;
151	    align-items: flex-start;
152	    gap: var(--rail-gap);
153	    overflow-x: auto;
154	    overflow-y: hidden;
155	    scroll-snap-type: x mandatory;
156	    scroll-padding-inline-start: 4px;
157	    scrollbar-width: none;
158	    padding: 4px;
159	    margin: -4px;
160	
161	    &::-webkit-scrollbar {
162	        display: none;
163	    }
164	}
165	
166	.rail__card {
167	    // Pin the card size so long titles never expand the flex item.
168	    // `min-width: 0` is needed because flex items default to `min-width: auto`
169	    // (their intrinsic content size), which would otherwise override the
170	    // flex-basis when the title wraps.
171	    flex: 0 0 var(--rail-card-width);
172	    width: var(--rail-card-width);
173	    max-width: var(--rail-card-width);
174	    min-width: 0;
175	    scroll-snap-align: start;
176	    position: relative;
177	    display: flex;
178	    flex-direction: column;
179	    color: inherit;
180	    border-radius: var(--rail-radius);
181	    transition:
182	        transform 0.2s ease,
183	        filter 0.2s ease;
184	
185	    &:hover {
186	        transform: translateY(-2px);
187	
188	        .rail__art {
189	            box-shadow:
190	                0 12px 22px -12px rgba(0, 0, 0, 0.45),
191	                0 0 0 1px var(--app-selection-border, rgba(47, 123, 255, 0.4));
192	        }
193	
194	        .rail__card-title {
195	            color: var(--app-selection-color, #2f7bff);
196	        }
197	    }
198	}
199	
200	.rail__card-link {
201	    display: flex;
202	    flex-direction: column;
203	    gap: 8px;
204	    min-width: 0;
205	    color: inherit;
206	    text-decoration: none;
207	    border-radius: inherit;
208	
209	    &:focus-visible {
210	        outline: 2px solid var(--app-selection-color, #2f7bff);
211	        outline-offset: 3px;
212	    }
213	}
214	
215	.rail__art {
216	    position: relative;
217	    overflow: hidden;
218	    border-radius: var(--rail-radius);
219	    background: var(--app-widget-bg, #1e2330);
220	    border: 1px solid var(--app-widget-header-border, rgba(255, 255, 255, 0.05));
221	    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
222	    transition: box-shadow 0.2s ease;
223	
224	    img {
225	        width: 100%;
226	        height: 100%;
227	        object-fit: cover;
228	        display: block;
229	    }
230	}
231	
232	.rail__art-fallback {
233	    position: absolute;
234	    inset: 0;
235	    display: flex;
236	    align-items: center;
237	    justify-content: center;
238	    background:
239	        radial-gradient(
240	            circle at 30% 20%,
241	            var(--app-selection-surface, rgba(120, 173, 255, 0.18)) 0%,
242	            transparent 55%
243	        ),
244	        var(--app-widget-bg, #1e2330);
245	
246	    mat-icon {
247	        font-size: 44px;
248	        width: 44px;
249	        height: 44px;
250	        color: var(--app-selection-color, #78adff);
251	        opacity: 0.55;
252	    }
253	}
254	
255	.rail__action-trigger {
256	    position: absolute;
257	    top: 8px;
258	    right: 8px;
259	    z-index: 3;
260	    width: 30px;
261	    height: 30px;
262	    padding: 3px;
263	    border-radius: 50%;
264	    color: #fff;
265	    background: transparent;
266	    border: 0;
267	    box-shadow: none;
268	    opacity: 0.92;
269	    transition:
270	        opacity 0.15s ease,
271	        transform 0.15s ease;
272	    --mdc-icon-button-state-layer-size: 30px;
273	
274	    mat-icon {
275	        font-size: 18px;
276	        width: 18px;
277	        height: 18px;
278	        line-height: 18px;
279	    }
280	
281	    &:hover,
282	    &:focus-visible {
283	        opacity: 1;
284	        transform: translateY(-1px);
285	    }
286	}
287	
288	.rail__menu-action--separated {
289	    border-top: 1px solid var(--app-separator);
290	    margin-top: 4px;
291	}
292	
293	.rail__menu-action--danger {
294	    color: var(--mat-sys-error);
295	
296	    mat-icon {
297	        color: var(--mat-sys-error);
298	    }
299	}
300	
301	.rail__meta {
302	    display: flex;
303	    flex-direction: column;
304	    gap: 3px;
305	    padding: 0 2px;
306	    min-width: 0;
307	}
308	
309	.rail__card-title {
310	    font-size: 0.85rem;
311	    font-weight: 600;
312	    line-height: 1.3;
313	    color: var(--app-heading-color, #1a1d23);
314	    white-space: nowrap;
315	    overflow: hidden;
