.rail__count {
    font-size: 0.78rem;
    font-weight: 500;
    line-height: 1;
    color: var(--app-muted-color, #8891a4);
    font-variant-numeric: tabular-nums;
    // Tiny capsule to read as a "count chip", not a number-in-text
    padding: 2px 8px;
    border-radius: 999px;
    background: color-mix(
        in srgb,
        var(--app-muted-color, #8891a4) 18%,
        transparent
    );
    letter-spacing: 0;
}

.rail__see-all {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    padding: 4px 8px 4px 10px;
    border-radius: 999px;
    font-size: 0.78rem;
    font-weight: 500;
    line-height: 1;
    letter-spacing: 0.005em;
    color: var(--app-muted-color, #8891a4);
    text-decoration: none;
    transition:
        color 0.15s ease,
        background-color 0.15s ease;

    mat-icon {
        font-size: 16px;
        width: 16px;
        height: 16px;
        transition: transform 0.15s ease;
    }

    &:hover {
        color: var(--app-selection-color, #2f7bff);
        background: color-mix(
            in srgb,
            var(--app-selection-color, #2f7bff) 12%,
            transparent
        );

        mat-icon {
            transform: translateX(2px);
        }
    }

    &:focus-visible {
        outline: 2px solid var(--app-selection-color, #2f7bff);
        outline-offset: 2px;
    }
}

.rail__viewport {
    position: relative;
    min-width: 0;

    // Soft edge gradients hint at horizontal scroll without any interaction.
    // Anchored to the viewport so they appear/disappear in sync with the
    // chevrons' `.rail__chev--visible` state.
    &::before,
    &::after {
        content: '';
        position: absolute;
        top: 0;
        bottom: 0;
        width: 32px;
        pointer-events: none;
        z-index: 1;
        opacity: 0;
        transition: opacity 0.2s ease;
    }

    &::before {
        left: 0;
        background: linear-gradient(
            to right,
            var(--app-content-bg, #161a22) 0%,
            transparent 100%
        );
    }

    &::after {
        right: 0;
        background: linear-gradient(
            to left,
            var(--app-content-bg, #161a22) 0%,
            transparent 100%
        );
    }

    // Show the correct edge gradient when scroll is possible in that direction
    &:has(.rail__chev--left.rail__chev--visible)::before {
        opacity: 0.9;
    }

    &:has(.rail__chev--right.rail__chev--visible)::after {
        opacity: 0.9;
    }

    &:hover .rail__chev--visible {
        opacity: 1;
        transform: translateY(-50%) scale(1);
    }
}

.rail__track {
    display: flex;
    align-items: flex-start;
    gap: var(--rail-gap);
    overflow-x: auto;
    overflow-y: hidden;
    scroll-snap-type: x mandatory;
    scroll-padding-inline-start: 4px;
    scrollbar-width: none;
    padding: 4px;
    margin: -4px;

    &::-webkit-scrollbar {
        display: none;
    }
}

.rail__card {
    // Pin the card size so long titles never expand the flex item.
    // `min-width: 0` is needed because flex items default to `min-width: auto`
    // (their intrinsic content size), which would otherwise override the
    // flex-basis when the title wraps.
    flex: 0 0 var(--rail-card-width);
    width: var(--rail-card-width);
    max-width: var(--rail-card-width);
    min-width: 0;
    scroll-snap-align: start;
    position: relative;
    display: flex;
    flex-direction: column;
    color: inherit;
    border-radius: var(--rail-radius);
    transition:
        transform 0.2s ease,
        filter 0.2s ease;

    &:hover {
        transform: translateY(-2px);

        .rail__art {
            box-shadow:
                0 12px 22px -12px rgba(0, 0, 0, 0.45),
                0 0 0 1px var(--app-selection-border, rgba(47, 123, 255, 0.4));
        }

        .rail__card-title {
            color: var(--app-selection-color, #2f7bff);
        }
    }
}

.rail__card-link {
    display: flex;
    flex-direction: column;
    gap: 8px;
    min-width: 0;
    color: inherit;
    text-decoration: none;
    border-radius: inherit;

    &:focus-visible {
        outline: 2px solid var(--app-selection-color, #2f7bff);
        outline-offset: 3px;
    }
}

.rail__art {
    position: relative;
    overflow: hidden;
    border-radius: var(--rail-radius);
    background: var(--app-widget-bg, #1e2330);
    border: 1px solid var(--app-widget-header-border, rgba(255, 255, 255, 0.05));
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
    transition: box-shadow 0.2s ease;

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
    }
}

.rail__art-fallback {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background:
        radial-gradient(
            circle at 30% 20%,
            var(--app-selection-surface, rgba(120, 173, 255, 0.18)) 0%,
            transparent 55%
        ),
        var(--app-widget-bg, #1e2330);

    mat-icon {
        font-size: 44px;
        width: 44px;
        height: 44px;
        color: var(--app-selection-color, #78adff);
        opacity: 0.55;
    }
}

.rail__action-trigger {
    position: absolute;
    top: 8px;
    right: 8px;
    z-index: 3;
    width: 30px;
    height: 30px;
    padding: 3px;
    border-radius: 50%;
    color: #fff;
    background: transparent;
    border: 0;
    box-shadow: none;
    opacity: 0.92;
    transition:
        opacity 0.15s ease,
        transform 0.15s ease;
    --mdc-icon-button-state-layer-size: 30px;

    mat-icon {
        font-size: 18px;
        width: 18px;
        height: 18px;
        line-height: 18px;
    }

    &:hover,
    &:focus-visible {
        opacity: 1;
        transform: translateY(-1px);
    }
}

.rail__menu-action--separated {
    border-top: 1px solid var(--app-separator);
    margin-top: 4px;
}

.rail__menu-action--danger {
    color: var(--mat-sys-error);

    mat-icon {
        color: var(--mat-sys-error);
    }
}

.rail__meta {
    display: flex;
    flex-direction: column;
    gap: 3px;
    padding: 0 2px;
    min-width: 0;
}

.rail__card-title {
    font-size: 0.85rem;
    font-weight: 600;
    line-height: 1.3;
    color: var(--app-heading-color, #1a1d23);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    letter-spacing: -0.005em;
    transition: color 0.15s ease;
}

.rail__card-subtitle {
    font-size: 0.72rem;
    font-weight: 500;
    line-height: 1.4;
    color: var(--app-muted-color, #8891a4);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    letter-spacing: 0.005em;
}

// Circular chevron — streaming-app pattern (Netflix/Apple TV+). High-contrast
// dark glass works against any card color, including the muted fallback tiles
// which previously camouflaged the buttons.
.rail__chev {
    position: absolute;
    top: 50%;
    transform: translateY(-50%) scale(0.96);
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    padding: 0;
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 50%;
    background: rgba(0, 0, 0, 0.72);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    color: #fff;
    cursor: pointer;
    opacity: 0;
    pointer-events: none;
    transition:
        opacity 0.18s ease,
        background-color 0.18s ease,
        transform 0.18s ease,
        box-shadow 0.18s ease;
    z-index: 2;
    box-shadow:
        0 4px 14px -4px rgba(0, 0, 0, 0.55),
        0 0 0 0 rgba(255, 255, 255, 0); // slot for hover ring

    mat-icon {
        font-size: 24px;
        width: 24px;
        height: 24px;
        line-height: 24px;
        // Keep icon crisp over bright content
        filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.5));
    }

    // Peek at rest when scroll is possible — hints the affordance exists
    // without requiring the user to hover first.
    &--visible {
        opacity: 0.5;
        pointer-events: auto;
    }

    &:hover {
        background: rgba(0, 0, 0, 0.88);
        transform: translateY(-50%) scale(1.08);
        box-shadow:
            0 8px 22px -6px rgba(0, 0, 0, 0.65),
            0 0 0 4px rgba(255, 255, 255, 0.06);
    }

    &:active {
        transform: translateY(-50%) scale(0.96);
    }

    &:focus-visible {
        outline: 2px solid var(--app-selection-color, #78adff);
        outline-offset: 3px;
    }

    &--left {
        left: 6px;
    }

    &--right {
        right: 6px;
    }
}

@media (hover: none) {
    .rail__chev {
        display: none;
    }

    .rail__viewport::before,
    .rail__viewport::after {
        display: none;
    }
}

@media (max-width: 720px) {
    :host {
        --rail-card-width: 140px;
    }
}

