83	
84	// Layer 0: backdrop. Two modes:
85	//   (1) Real backdrop (`.hero--has-backdrop`): sharp wide image with no blur.
86	//   (2) Blurred-poster fallback: heavy blur + scale so the poster's colours
87	//       wash across the full panel without the portrait edges showing.
88	.hero__backdrop {
89	    position: absolute;
90	    inset: 0;
91	    background-size: cover;
92	    background-position: center 25%;
93	    background-repeat: no-repeat;
94	    z-index: 0;
95	    pointer-events: none;
96	
97	    // Fallback: blurred poster.
98	    filter: blur(40px) saturate(1.5);
99	    transform: scale(1.5);
100	    opacity: 0.9;
101	}
102	
103	.hero--has-backdrop .hero__backdrop {
104	    filter: none;
105	    transform: none;
106	    opacity: 1;
107	}
108	
109	.hero--has-default-backdrop .hero__backdrop {
110	    filter: none;
111	    transform: none;
112	    opacity: 0.95;
113	}
114	
115	.hero__image-probe {
116	    position: absolute;
117	    width: 1px;
118	    height: 1px;
119	    clip-path: inset(50%);
120	    opacity: 0;
121	    pointer-events: none;
122	}
123	
124	// Layer 1: vignette. Scrim behind the poster card (contrast) and on the
125	// right edge (text legibility). Middle stays mostly transparent so the
126	// backdrop colours show through. Darkens further when a sharp backdrop is
127	// present, since real photography has more focal variation than a blur wash.
128	.hero__vignette {
129	    position: absolute;
130	    inset: 0;
131	    z-index: 1;
132	    pointer-events: none;
133	    background:
134	        linear-gradient(
135	            90deg,
136	            color-mix(
137	                    in srgb,
138	                    var(--app-widget-header-bg, #232840) 55%,
139	                    transparent
140	                )
141	                0%,
142	            color-mix(
143	                    in srgb,
144	                    var(--app-widget-header-bg, #232840) 10%,
145	                    transparent
146	                )
147	                45%,
148	            color-mix(
149	                    in srgb,
150	                    var(--app-widget-header-bg, #232840) 65%,
151	                    transparent
152	                )
153	                100%
154	        ),
155	        linear-gradient(
156	            to bottom,
157	            transparent 55%,
158	            color-mix(
159	                    in srgb,
160	                    var(--app-widget-header-bg, #232840) 35%,
161	                    transparent
162	                )
163	                100%
164	        );
165	}
166	
167	.hero--has-backdrop .hero__vignette {
168	    background:
169	        linear-gradient(
170	            90deg,
171	            rgba(0, 0, 0, 0.55) 0%,
172	            rgba(0, 0, 0, 0.2) 35%,
173	            rgba(0, 0, 0, 0.78) 100%
174	        ),
175	        linear-gradient(
176	            to bottom,
177	            rgba(0, 0, 0, 0) 40%,
178	            rgba(0, 0, 0, 0.45) 100%
179	        );
180	}
181	
182	// Layer 2: sharp poster in native 2:3 aspect (no more 16:9 crop).
183	.hero__poster {
184	    position: relative;
185	    z-index: 2;
186	    width: var(--hero-poster-width);
187	    aspect-ratio: 2 / 3;
188	    border-radius: 12px;
189	    overflow: hidden;
190	    background: var(--app-widget-bg, #1e2330);
191	    border: 1px solid var(--app-widget-header-border, rgba(255, 255, 255, 0.1));
192	    box-shadow: 0 8px 24px -10px rgba(0, 0, 0, 0.55);
193	    align-self: center;
194	
