.hero {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, var(--hero-poster-width)) minmax(0, 1fr);
    gap: 24px;
    padding: 20px;
    text-decoration: none;
    color: inherit;
    border-radius: 18px;
    overflow: hidden;
    isolation: isolate;
    background: var(--app-widget-header-bg, #232840);
    border: 1px solid var(--app-widget-header-border, rgba(255, 255, 255, 0.08));
    box-shadow:
        0 1px 2px rgba(0, 0, 0, 0.2),
        0 12px 32px -18px var(--app-selection-glow, rgba(120, 173, 255, 0.4));
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;

    --hero-poster-width: 160px;

    &:hover {
        transform: translateY(-2px);
        box-shadow:
            0 1px 2px rgba(0, 0, 0, 0.2),
            0 20px 40px -20px
                var(--app-selection-glow, rgba(120, 173, 255, 0.55));
    }

    // No-image fallback keeps the accent gradient so the hero is never flat.
    &:not(.hero--with-image) {
        background:
            var(
                --app-accent-gradient,
                linear-gradient(
                    135deg,
                    rgba(99, 102, 241, 0.12) 0%,
                    rgba(168, 85, 247, 0.07) 100%
                )
            ),
            var(--app-widget-header-bg, #232840);
    }
}

// Layer 0: backdrop. Two modes:
//   (1) Real backdrop (`.hero--has-backdrop`): sharp wide image with no blur.
//   (2) Blurred-poster fallback: heavy blur + scale so the poster's colours
//       wash across the full panel without the portrait edges showing.
.hero__backdrop {
    position: absolute;
    inset: 0;
    background-size: cover;
    background-position: center 25%;
    background-repeat: no-repeat;
    z-index: 0;
    pointer-events: none;

    // Fallback: blurred poster.
    filter: blur(40px) saturate(1.5);
    transform: scale(1.5);
    opacity: 0.9;
}

.hero--has-backdrop .hero__backdrop {
    filter: none;
    transform: none;
    opacity: 1;
}

.hero--has-default-backdrop .hero__backdrop {
    filter: none;
    transform: none;
    opacity: 0.95;
}

.hero__image-probe {
    position: absolute;
    width: 1px;
    height: 1px;
    clip-path: inset(50%);
    opacity: 0;
    pointer-events: none;
}

// Layer 1: vignette. Scrim behind the poster card (contrast) and on the
// right edge (text legibility). Middle stays mostly transparent so the
// backdrop colours show through. Darkens further when a sharp backdrop is
// present, since real photography has more focal variation than a blur wash.
.hero__vignette {
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    background:
        linear-gradient(
            90deg,
            color-mix(
                    in srgb,
                    var(--app-widget-header-bg, #232840) 55%,
                    transparent
                )
                0%,
            color-mix(
                    in srgb,
                    var(--app-widget-header-bg, #232840) 10%,
                    transparent
                )
                45%,
            color-mix(
                    in srgb,
                    var(--app-widget-header-bg, #232840) 65%,
                    transparent
                )
                100%
        ),
        linear-gradient(
            to bottom,
            transparent 55%,
            color-mix(
                    in srgb,
                    var(--app-widget-header-bg, #232840) 35%,
                    transparent
                )
                100%
        );
}

.hero--has-backdrop .hero__vignette {
